(()=>{const section=document.querySelector('#brands'),panels=[...section.querySelectorAll('.brand-exhibit')],buttons=[...section.querySelectorAll('[data-brand]')],reduced=matchMedia('(prefers-reduced-motion: reduce)');let target=0,current=0,frame=0,last=0;function paint(){const active=Math.min(3,Math.max(0,Math.round(current)));panels.forEach((p,i)=>{const d=i-current,opacity=Math.max(0,1-Math.abs(d)*1.45);p.style.setProperty('--exhibit-opacity',opacity);p.style.setProperty('--caption-opacity',Math.max(0,1-Math.abs(d)*4));p.style.setProperty('--exhibit-x',d*65+'%');p.style.setProperty('--exhibit-scale',1-Math.min(.28,Math.abs(d)*.22));p.style.setProperty('--exhibit-blur',Math.min(9,Math.abs(d)*8)+'px');p.style.setProperty('--type-x',d*-16+'%');p.inert=i!==active;p.setAttribute('aria-hidden',String(i!==active));});buttons.forEach((b,i)=>{b.setAttribute('aria-current',i===active?'true':'false');b.style.setProperty('--brand-progress',Math.max(0,Math.min(1,current-i+1)));});}function tick(now){const dt=last?Math.min((now-last)/1000,.05):1/60;last=now;current+=(target-current)*(1-Math.exp(-dt*11));if(Math.abs(target-current)<.001){current=target;frame=0;last=0;paint();return;}paint();frame=requestAnimationFrame(tick);}function read(){if(reduced.matches){cancelAnimationFrame(frame);frame=0;panels.forEach(p=>{p.inert=false;p.removeAttribute('aria-hidden');});return;}const rect=section.getBoundingClientRect(),span=Math.max(1,section.offsetHeight-innerHeight);target=Math.max(0,Math.min(3,-rect.top/span*3.3));if(!frame)frame=requestAnimationFrame(tick);}buttons.forEach((b,i)=>b.onclick=()=>{const span=section.offsetHeight-innerHeight;scrollTo({top:section.getBoundingClientRect().top+scrollY+span*i/3.3,behavior:reduced.matches?'instant':'smooth'});});addEventListener('scroll',read,{passive:true});addEventListener('resize',read);reduced.addEventListener('change',read);paint();read();})();
